function makeSamples(){return ['이차방정식과 두 근','이등변삼각형의 각도','다항함수의 미분계수','일차함수의 식'].map((title,i)=>{const src=sampleImage(i);return{id:uid(),title,src,original:src,width:680,height:[235,285,235,245][i],difficulty:[2,3,4,2][i],answer:['④ 13','70°','③ 0','5'][i],type:'예시',solution:null,scale:100,breakBefore:false}})}
function getLayout(){const s=state.settings,px=794/210,m=s.margin*px,g=s.gap*px,cw=(794-2*m-(s.columns-1)*g)/s.columns,top=m+111,limit=1123-m-29;let list=[],page={items:[],answerKey:false},y=top,row=[],rowHeight=0;const pushPage=()=>{if(page.items.length)list.push(page);page={items:[],answerKey:false};y=top;row=[];rowHeight=0};for(let i=0;i<state.questions.length;i++){const q=state.questions[i];if(q.breakBefore&&page.items.length)pushPage();let iw=cw*q.scale/100,ih=q.height/q.width*iw;const space=s.solution?(q.solution??s.solutionSpace)*px:0;const maxH=limit-top;ih=Math.min(ih,Math.max(40,maxH-25-space-(s.answerLine?25:8)-22));let h=25+ih+space+(s.answerLine?25:8)+22;if(h>maxH){h=maxH;ih=Math.max(30,h-25-space-(s.answerLine?25:8)-22)}if(row.length===s.columns){y+=rowHeight+18;row=[];rowHeight=0}if(y+h>limit&&page.items.length){pushPage()}const col=row.length;const item={q,index:i,x:m+col*(cw+g),y,w:cw,h,iw,ih,space};page.items.push(item);row.push(item);rowHeight=Math.max(rowHeight,h)}if(page.items.length)list.push(page);if(s.answerKey&&state.questions.length){const measure=document.createElement('canvas').getContext('2d');measure.font='12px Noto Sans KR,Malgun Gothic,Arial,sans-serif';const maxWidth=794-2*m-48;let answers=[],used=0;for(let i=0;i<state.questions.length;i++){const q=state.questions[i];let lines=1,line='';for(const ch of (q.answer||'정답 미입력')){if(measure.measureText(line+ch).width>maxWidth&&line){lines++;line=ch}else line+=ch}const h=Math.max(49,lines*18+29);if(used+h>limit-(top+10)&&answers.length){list.push({answerKey:true,answers,items:[]});answers=[];used=0}answers.push({q,index:i,h});used+=h}if(answers.length)list.push({answerKey:true,answers,items:[]})}return list}
function fitZoom(){const stage=$('#canvas-stage');return Math.max(.22,Math.min(.95,(stage.clientWidth-44)/794))}
function render(){pages=getLayout();if(autoFit)zoom=fitZoom();renderList();renderPreview();renderSelected();$('#question-count').textContent=state.questions.length;$('#crumb-title').textContent=state.settings.title||'제목 없는 문제지';$('#page-summary').textContent=pages.length+'페이지 · 총 '+state.questions.length+'문제';$('#zoom-value').textContent=Math.round(zoom*100)+'%';$('#undo-button').disabled=!undoStack.length;$('#redo-button').disabled=!redoStack.length;$('#export-button').disabled=!state.questions.length}
function renderList(){const levels=['','기초','기본','보통','심화','최상'];$('#question-list').innerHTML=state.questions.map((q,i)=>'<article class="question-card '+(q.id===selected?'selected':'')+'" draggable="true" data-id="'+q.id+'" tabindex="0" aria-label="'+(i+1)+'번 '+esc(q.title)+'"><div class="question-topline"><span class="question-num">'+String(i+1).padStart(2,'0')+'</span><span>'+esc(q.title.length>13?q.title.slice(0,13)+'…':q.title)+'</span><span class="question-type">'+esc(q.type)+'</span><button class="icon-button" data-delete="'+q.id+'" aria-label="이 문제 삭제">'+icon('close')+'</button></div><img class="question-thumb" src="'+q.src+'" alt="'+esc(q.title)+'"><div class="question-card-bottom">'+starsHTML(q.difficulty)+'<span class="difficulty-label">'+levels[q.difficulty]+'</span><button class="edit-photo" data-edit="'+q.id+'">'+icon('sparkles')+'사진 보정</button></div></article>').join('')}
function paperHeader(answerKey=false){const s=state.settings,m=s.margin*794/210;return '<div class="paper-header" style="top:'+m+'px;left:'+m+'px;width:'+(794-2*m)+'px"><div class="paper-meta">'+esc(s.subtitle||'MY WORKSHEET')+(answerKey?' · ANSWER KEY':'')+'</div><h2>'+esc(s.title||'제목 없는 문제지')+(answerKey?' · 정답':'')+'</h2><div class="paper-info"><span>'+esc(s.date||'차근차근 풀어보세요. 오늘도 한 걸음 더.')+'</span>'+(s.nameField?'<span class="name-blank">이름 __________________　 날짜 ____________</span>':'')+'</div></div>'}
function renderPreview(){const s=state.settings,m=s.margin*794/210,g=s.gap*794/210;$('#canvas-empty').hidden=!!state.questions.length;$('#paper-stack').innerHTML=pages.map((p,i)=>'<div class="paper-wrapper" style="width:'+(794*zoom)+'px;height:'+(1123*zoom)+'px"><div class="paper" style="transform:scale('+zoom+')">'+paperHeader(p.answerKey)+(s.divider&&s.columns===2&&!p.answerKey?'<div class="paper-column-divider" style="left:397px;top:'+(m+111)+'px;height:'+(1123-m-29-m-111)+'px"></div>':'')+(p.answerKey?'<div class="answer-key-content" style="position:absolute;left:'+m+'px;right:'+m+'px;top:'+(m+121)+'px">'+p.answers.map(a=>'<div class="answer-key-row" style="height:'+a.h+'px"><b>'+String(a.index+1).padStart(2,'0')+'</b><span>'+esc(a.q.answer||'정답 미입력')+'</span></div>').join('')+'</div>':p.items.map(it=>'<article class="paper-question '+(it.q.id===selected?'selected':'')+'" data-id="'+it.q.id+'" draggable="true" style="left:'+it.x+'px;top:'+it.y+'px;width:'+it.w+'px;height:'+it.h+'px"><div class="paper-question-head"><span class="paper-question-number">'+String(it.index+1).padStart(2,'0')+'</span>'+(s.stars?'<span class="paper-stars">'+'★'.repeat(it.q.difficulty)+'☆'.repeat(5-it.q.difficulty)+'</span>':'')+'</div><img class="paper-problem-image" src="'+it.q.src+'" style="width:'+it.iw+'px;height:'+it.ih+'px;object-fit:contain;object-position:left top" alt="'+esc(it.q.title)+'">'+(s.solution?'<div class="solution-area '+s.lineStyle+'" style="height:'+it.space+'px">'+(s.lineStyle==='blank'?'<span class="solution-label">풀이</span>':'')+'</div>':'')+(s.answerLine?'<div class="paper-answer">답 ____________________</div>':'')+'</article>').join(''))+'<div class="paper-footer" style="left:'+m+'px;width:'+(794-2*m)+'px"><span>'+esc(s.subtitle||'나의 문제지')+'</span><span>'+String(i+1).padStart(2,'0')+' / '+String(pages.length).padStart(2,'0')+'</span></div></div><div class="page-caption">'+(p.answerKey?'정답지':'문제지')+' · '+(i+1)+'페이지</div></div>').join('')}
function renderSelected(){const q=state.questions.find(q=>q.id===selected);$('#selected-question-content').innerHTML=q?'<section class="settings-section"><h4>'+String(state.questions.indexOf(q)+1).padStart(2,'0')+'　선택한 문제</h4><img class="selected-preview" src="'+q.src+'" alt="선택한 문제"><label class="field-label">난이도</label>'+starsHTML(q.difficulty,'editor-stars')+'<label class="field-label" for="selected-name">문제 이름</label><input class="text-input" id="selected-name" maxlength="100" value="'+esc(q.title)+'"><label class="field-label" for="selected-answer">정답</label><input class="text-input" id="selected-answer" maxlength="300" placeholder="정답지에 들어갈 답" value="'+esc(q.answer)+'"><button class="button secondary full" id="selected-edit" style="margin-top:14px">'+icon('sparkles')+'사진 보정하기</button></section><section class="settings-section"><h4>이 문제의 배치</h4><div class="range-label"><label for="question-scale">사진 크기</label><output>'+q.scale+'%</output></div><input type="range" id="question-scale" min="50" max="100" step="5" value="'+q.scale+'"><div class="range-label"><label for="question-solution">개별 풀이 공간</label><output>'+(q.solution??state.settings.solutionSpace)+' mm</output></div><input type="range" id="question-solution" min="0" max="75" value="'+(q.solution??state.settings.solutionSpace)+'"><button class="text-button" id="reset-question-space">문제지 기본값 사용</button><label class="toggle-row"><span>새 페이지에서 시작</span><input type="checkbox" id="question-break" '+(q.breakBefore?'checked':'')+'><span class="toggle"></span></label><div class="selected-commands"><button id="move-prev" class="button secondary" '+(state.questions.indexOf(q)===0?'disabled':'')+'>'+icon('up')+'앞으로</button><button id="move-next" class="button secondary" '+(state.questions.indexOf(q)===state.questions.length-1?'disabled':'')+'>'+icon('down')+'뒤로</button></div><button class="button full delete-button" id="selected-delete">'+icon('trash')+'이 문제 삭제</button></section>':'<div class="question-settings-empty">문제 목록이나 A4 화면에서<br>수정할 문제를 선택해 주세요.</div>';$$('#selected-question-content input[type=range]').forEach(paintRange)}
function syncSettings(){const s=state.settings;const text={'sheet-title':'title','sheet-subtitle':'subtitle','sheet-date':'date',margin:'margin','column-gap':'gap','solution-space':'solutionSpace'};Object.entries(text).forEach(([id,k])=>$('#'+id).value=s[k]);const checks={'name-field':'nameField',divider:'divider','solution-toggle':'solution','show-stars':'stars','answer-line':'answerLine','answer-key':'answerKey'};Object.entries(checks).forEach(([id,k])=>$('#'+id).checked=s[k]);$('#col-one').classList.toggle('active',s.columns===1);$('#col-two').classList.toggle('active',s.columns===2);$$('[data-line]').forEach(b=>b.classList.toggle('active',s.lineStyle===b.dataset.line));$('#margin-value').innerHTML=s.margin+' <small>mm</small>';$('#gap-value').innerHTML=s.gap+' <small>mm</small>';$('#solution-value').innerHTML=s.solutionSpace+' <small>mm</small>';$('#solution-controls').hidden=!s.solution;$$('input[type=range]').forEach(paintRange)}
function paintRange(e){const percent=(e.value-e.min)/(e.max-e.min)*100;e.style.background='linear-gradient(to right,#91a87c '+percent+'%,#e5eadc '+percent+'%)'}
function selectQuestion(id,tab=false){selected=id;renderList();renderPreview();renderSelected();if(tab)switchTab('question')}
function switchTab(tab){const a=tab==='layout';$('#layout-tab').classList.toggle('active',a);$('#question-tab').classList.toggle('active',!a);$('#layout-tab').setAttribute('aria-selected',a);$('#question-tab').setAttribute('aria-selected',!a);$('#layout-settings').hidden=!a;$('#question-settings').hidden=a}
function removeQuestion(id){update(()=>{state.questions=state.questions.filter(q=>q.id!==id);if(selected===id)selected=state.questions[0]?.id||null});toast('문제를 삭제했어요. 실행 취소로 되돌릴 수 있어요.')}
async function addFiles(files){const arr=[...files];if(!arr.length)return;const images=arr.filter(f=>/^image\/(jpeg|png|webp)$/.test(f.type)||/\.(jpe?g|png|webp)$/i.test(f.name));if(images.length!==arr.length)toast('JPG, PNG, WEBP 사진을 선택해 주세요.');if(!images.length)return;if(state.questions.length+images.length>100){toast('한 프로젝트에 최대 100문제까지 추가할 수 있어요.');return}$('#layout-status').textContent='사진을 읽고 있어요…';const results=[];for(const f of images){try{if(f.size>30*1024*1024)throw Error('size');const url=URL.createObjectURL(f);let im;try{im=await loadImage(url)}finally{URL.revokeObjectURL(url)}const ratio=Math.min(1,1800/Math.max(im.naturalWidth,im.naturalHeight));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(im.naturalWidth*ratio));c.height=Math.max(1,Math.round(im.naturalHeight*ratio));const ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.drawImage(im,0,0,c.width,c.height);const src=c.toDataURL('image/png');results.push({id:uid(),title:f.name.replace(/\.[^.]+$/,'').slice(0,100),src,original:src,width:c.width,height:c.height,difficulty:3,answer:'',type:'사진',solution:null,scale:100,breakBefore:false})}catch{toast(f.name+' 파일을 읽지 못했어요. 30MB 이하의 사진을 사용해 주세요.')}}if(results.length){update(()=>{state.questions.push(...results);selected=results[0].id});toast(results.length+'개의 문제 사진을 추가했어요.')}$('#layout-status').textContent='자동 배치 완료';$('#file-input').value=''}
$('#upload-zone').onclick=$('#empty-upload').onclick=()=>$('#file-input').click();$('#file-input').onchange=e=>addFiles(e.target.files);const zone=$('#upload-zone');zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag-over')};zone.ondragleave=()=>zone.classList.remove('drag-over');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag-over');addFiles(e.dataTransfer.files)};
$('#layout-tab').onclick=()=>switchTab('layout');$('#question-tab').onclick=()=>switchTab('question');$('#help-button').onclick=()=>$('#help-dialog').showModal();$('#library-menu').onclick=()=>$('#help-dialog').showModal();
$('#question-list').addEventListener('click',e=>{const c=e.target.closest('.question-card');if(!c)return;const id=c.dataset.id;if(e.target.closest('[data-delete]'))return removeQuestion(id);if(e.target.closest('[data-edit]'))return openEditor(id);const st=e.target.closest('[data-star]');if(st){selected=id;return update(()=>state.questions.find(q=>q.id===id).difficulty=+st.dataset.star)}selectQuestion(id)});
